template:
@php
    $html = is_string($body) ? trim($body) : '';
    if ($html !== '' && ! str_starts_with($html, '<')) {
        $html = implode('', array_map(static fn (string $line): string => '<p>'.e(trim($line)).'</p>', preg_split('/\R+/u', $html) ?: []));
    }
@endphp
@if ($heading || $html !== '')
<section class="b-text b-text--{{ $width === 'wide' ? 'wide' : 'narrow' }}" data-wx-block="text"@webxOverlap($overlap ?? false)>
    @webxOverlapEdge($overlap ?? false, $overlap_edge ?? null, $overlap_edge_narrow ?? null)
    <div class="b-text__inner site-prose" @webxReveal('', $no_reveal)>
        @if ($heading)
            <h2 class="b-text__heading">@webxAccent($heading)</h2>
        @endif
        @if ($html !== '')
            <div class="b-text__body">{!! $html !!}</div>
        @endif
    </div>
</section>
@endif

styles:
.b-text {
    padding-block: var(--site-section-space, var(--site-space-5));
}

.b-text--narrow .b-text__inner {
    max-width: 42rem;
}

.b-text__heading {
    margin: 0 0 var(--site-section-title-space, var(--site-space-4));
}

/* The section's H2 type (THEMES §7.2): unset, the prose's own, and only where the prose applies
   (in the main column and under site-prose), so that nothing changes until a site sets it. */
.b-text__heading:where(.site-main *, .site-prose *) {
    font-family: var(--site-section-title-font, var(--site-font-heading));
    font-size: var(--site-section-title-size, var(--site-font-size-2));
    line-height: var(--site-section-title-line-height, 1.2);
    /* Unset, nothing: an inherited property falls back to the parent's. */
    text-transform: var(--site-section-title-case);
}

.b-text__body > :first-child {
    margin-top: 0;
}

.b-text__body > :last-child {
    margin-bottom: 0;
}
